{
  "findings": [
    {
      "check_id": "AVD-AZU-0023",
      "title": "Security alert policy does not alert account admins.",
      "resource": "azurerm_monitor_activity_log_alert.negative1",
      "severity": "LOW",
      "explanation": "The activity log alert does not include email notifications to subscription owners or administrators, which could delay response to critical events."
    }
  ],
  "patched_code": "resource "azurerm_monitor_activity_log_alert" "negative1" {
  name                = "example-activitylogalert"
  resource_group_name = azurerm_resource_group.example.name
  location            = azurerm_resource_group.example.location
  scopes              = [azurerm_resource_group.example.id]
  description         = "Negative sample"

  criteria {
    resource_id    = azurerm_storage_account.to_monitor.id
    operation_name = "Microsoft.Network/networkSecurityGroups/delete"
    category       = "Administrative"
  }

  action {
    action_group_id = azurerm_monitor_action_group.main.id

    webhook_properties = {
      from = "terraform"
    }
  }

  action {
    action_group_id = azurerm_monitor_action_group.main.id

    email_subject = "Alert: Activity Log Event"
    email_addresses = ["admin@example.com"]
  }
}
",
  "fix_summary": "Added an email notification action to the activity log alert to ensure subscription owners or administrators are notified of critical events."
}
